{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Ketoprofen, a small lipophilic carboxylic acid with an aromatic ketone, has an absolute oral bioavailability of ≥92% in humans, supporting high F for the similarly sized, weakly acidic, moderately lipophilic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Diflunisal, another small acidic aromatic drug, showed 89.5% absolute oral bioavailability versus IV, supporting high oral bioavailability for the query's weak-acid, low-molecular-weight profile.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A coumarin/chromenone-containing analogue (Z18483535) had 55.7% human oral bioavailability, directly above the 20% threshold and supporting high F for the coumarin-based query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Felbamate has >90% absolute oral bioavailability in humans, demonstrating that small, moderately polar oral drugs can achieve high systemic exposure, consistent with the query's favorable absorption properties.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is warfarin, a small weakly acidic 4-hydroxycoumarin with favorable physicochemical properties. Multiple human absolute bioavailability measurements for structurally related small acidic oral drugs (ketoprofen ≥92%, diflunisal 89.5%, a coumarin analogue 55.7%) and other small oral drugs (>90%) support high oral bioavailability. Low-bioavailability comparators such as cromolyn, alendronate, and baicalein are structurally dissimilar and not transferable. Therefore, F ≥20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule itself is included in the evidence set.",
    "All provided analogues have low Morgan similarity (≤0.29), limiting structural transferability.",
    "No data on first-pass metabolism or enantiomer-specific absorption for the query are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

